use super::*;
use semio_framework_job_testing_caller::{bank_run,bank_source_parent};
use semio_framework_value_control_contract::{RetainedWorkOutcome,RetainedWorkPoll};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
fn settle(poll:RetainedWorkPoll<RetainedCloneStep,OriginalSourceCloseFailure>)->RetainedWorkOutcome<RetainedCloneStep,OriginalSourceCloseFailure>{let RetainedWorkPoll::Complete(turn)=poll else{panic!("funded original Source close stayed pending")};turn}
#[test]
fn original_source_parent_closes_lending_before_child_then_separate_terminal_header(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let bank_grant=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};
 let mut bank=EffectBank::new(Wallet::from_profile(&serde_json::json!({"items":s["items"],"copyBytes":s["copyBytes"],"capacityBytes":s["capacityBytes"],"releaseBytes":s["releaseBytes"],"depth":s["depth"],"fuel":s["maximumTurns"]})));
 let mut authority_actual=None;let(authority,_)=JobPayloadAuthority::admit(OperationId(row["operation"].as_u64().unwrap()),Generation(row["generation"].as_u64().unwrap()),RetainedCloneGrant{maximum_items:1,..bank_grant},&mut authority_actual).result.unwrap().unwrap();
 let(token,_)=CancelToken::admit_root(RetainedCloneGrant{maximum_items:1,..bank_grant}).result.unwrap().unwrap();
 let mut parent=bank_source_parent(&mut bank,authority,token);let identity=parent.source_identity().unwrap();let source=parent.payload_authority_identity().unwrap();let demand=parent.retirement_demands().unwrap();assert_eq!(demand,RetirementDemand{depth:1,..Default::default()});
 let none=RetainedCloneGrant{maximum_items:0,..bank.wallet().remaining()};let(poll,admitted)=bank_run(&mut bank,none,1,|effect|parent.close_step(effect));let denied=settle(poll);assert_eq!(admitted,None);assert_eq!(denied.work,u128::from(row["deniedWork"].as_u64().unwrap()));assert_eq!(denied.result.unwrap().progress(),RetainedCloneProgress::default());assert!(parent.lending_is_open());assert_eq!(parent.source_identity().unwrap(),identity);assert_eq!(parent.payload_authority_identity().unwrap(),source);
 let mut work=Vec::new();for turn in 0..s["maximumTurns"].as_u64().unwrap(){if parent.terminal_is_empty(){break;}let quoted=parent.retirement_work_demand().unwrap();let issued=RetainedCloneGrant{maximum_items:1,..bank.wallet().remaining()};let(poll,admitted)=bank_run(&mut bank,issued,quoted,|effect|parent.close_step(effect));let next=settle(poll);assert_eq!(admitted,Some(true));assert_eq!(next.work,u128::from(quoted));work.push(next.work);let p=next.result.unwrap().progress();assert_eq!(p.copied_bytes,row["copyBytes"].as_u64().unwrap()as usize);if turn==0{assert!(!parent.lending_is_open());assert_eq!(parent.source_identity().unwrap(),identity);assert_eq!(parent.payload_authority_identity().unwrap(),source);}}
 assert!(parent.terminal_is_empty());assert_eq!(serde_json::to_value(work).unwrap(),row["actualWork"]);assert_eq!(parent.retirement_work_demand().unwrap(),0);let issued=RetainedCloneGrant{maximum_items:1,..bank.wallet().remaining()};let(poll,_)=bank_run(&mut bank,issued,1,|effect|parent.close_step(effect));let cached=settle(poll);assert_eq!(cached.work,u128::from(row["cachedWork"].as_u64().unwrap()));assert_eq!(cached.result.unwrap().progress(),RetainedCloneProgress::default());drop(parent);
}
